import{_ as p,a0 as l,w as r,s as u,ao as n,I as i,a1 as s,A as o,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"如何安裝和使用 Latte Dock | LCTT x X-CMD","titleTemplate":false,"description":"如何安裝和使用 Latte Dock | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何安裝和使用 Latte Dock | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何安裝和使用 Latte Dock | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20211204 How to Install and Use Latte Dock on Ubuntu and Other Linux Distributions","title":"如何安裝和使用 Latte Dock","tag":"202203","desc":""},"relativePath":"202203/20211204 How to Install and Use Latte Dock on Ubuntu and Other Linux Distributions.md","filePath":"[post].md"}'),d={name:"202203/20211204 How to Install and Use Latte Dock on Ubuntu and Other Linux Distributions.md"};function b(c,t,k,h,m,g){const e=l("Link");return r(),u("div",null,[t[27]||(t[27]=n('<h1 id="如何安裝和使用-latte-dock" tabindex="-1">如何安裝和使用 Latte Dock <a class="header-anchor" href="#如何安裝和使用-latte-dock" aria-label="Permalink to “如何安裝和使用 Latte Dock”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202203/09/091040v3n0vlxvt9a0zokx.jpg" alt=""></p><p>你知道什麼是“<ruby>停靠區<rt>Dock</rt></ruby>” 吧，它通常是你的應用程序“停靠”的底欄，以便快速訪問。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/latte-dock.webp?resize=800%2C167&amp;ssl=1" alt=""></p><p>許多發行版和桌面環境都提供了某種停靠實現。如果你的發行版沒有“<ruby>停靠區<rt>Dock</rt></ruby>”，或者你想嘗試一些新的停靠應用，Latte Dock 是一個不錯的選擇。它類似於 macOS 上的停靠區，每次你用鼠標懸停在任何停靠對象上時，都會有一個的拋物線動畫。</p><p>在本教程中，我將告訴你如何在 Ubuntu 上安裝 Latte Dock。我還會展示一些關於使用和定製 Latte Dock 的事情。</p><h3 id="在-ubuntu-上安裝-latte-dock" tabindex="-1">在 Ubuntu 上安裝 Latte Dock <a class="header-anchor" href="#在-ubuntu-上安裝-latte-dock" aria-label="Permalink to “在 Ubuntu 上安裝 Latte Dock”">​</a></h3>',7)),i("p",null,[s(e,{href:"https://invent.kde.org/plasma/latte-dock"},{default:o(()=>[...t[0]||(t[0]=[a("Latte Dock",-1)])]),_:1}),t[1]||(t[1]=a(" 是一個流行的應用程序，可以從大多數 Linux 發行版的官方軟件庫中獲得。也就是説你可以使用你的發行版的軟件中心或軟件包管理器來安裝 Latte dock。",-1))]),t[28]||(t[28]=n('<p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/latte-ubuntu-software-center.png?resize=800%2C384&amp;ssl=1" alt="Latte 可以從軟件中心獲得"></p><p>在 Ubuntu 和其他基於 Ubuntu 的發行版，如 elementary OS、Linux Mint、Pop!_OS、Zorin OS 上，使用 <code>apt</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install latte-dock</span></span></code></pre></div><p>這就行了！現在你已經在 Ubuntu 上安裝了 Latte Dock。</p><h4 id="停用-ubuntu-自帶的停靠區-針對-ubuntu-用户" tabindex="-1">停用 Ubuntu 自帶的停靠區（針對 Ubuntu 用户） <a class="header-anchor" href="#停用-ubuntu-自帶的停靠區-針對-ubuntu-用户" aria-label="Permalink to “停用 Ubuntu 自帶的停靠區（針對 Ubuntu 用户）”">​</a></h4>',5)),i("p",null,[t[3]||(t[3]=a("在你啓動你閃亮的新停靠區之前，我建議你禁用 Ubuntu 默認提供的停靠區。這裏有一個 ",-1)),s(e,{href:"https://itsfoss.com/disable-ubuntu-dock/"},{default:o(()=>[...t[2]||(t[2]=[a("關於如何禁用 Ubuntu 的停靠區的指南",-1)])]),_:1}),t[4]||(t[4]=a("。",-1))]),t[29]||(t[29]=n('<p>要禁用停靠區，請在你的終端輸入以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gnome-extensions disable ubuntu-dock@ubuntu.com</span></span></code></pre></div><p>如果你最終改變了主意，你可以用以下命令再次啓用 Ubuntu 停靠區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gnome-extensions enable ubuntu-dock@ubuntu.com</span></span></code></pre></div><blockquote><p>注意：</p><p>這不能禁用 Pop!_OS 20.04 LTS 上的默認停靠區（儘管它在桌面上默認是隱藏的；只在活動概覽中可見）。在使用 COSMIC 桌面環境/擴展的 Pop!_OS 上，你可以通過“<ruby>設置<rt>Settings</rt></ruby>”應用中的“<ruby>桌面<rt>Desktop</rt></ruby> -&gt; <ruby>停靠區<rt>Dock</rt></ruby>”來禁用或啓用停靠區。</p></blockquote><h3 id="開始使用-latte-dock" tabindex="-1">開始使用 Latte Dock <a class="header-anchor" href="#開始使用-latte-dock" aria-label="Permalink to “開始使用 Latte Dock”">​</a></h3><p>我在教程中使用的是 Pop!_OS，但這些步驟適用於任何 Linux 發行版。</p><p>一旦安裝完畢，你會在你的應用程序抽屜裏發現一個 Latte Dock 的啓動器圖標。你可以在這裏訪問它，或者按 <code>Super</code> 鍵（通常是 <code>Windows</code> 鍵；如果你有 Mac 鍵盤，則按 <code>Command</code> 鍵）鍵 + <code>A</code>。</p><p>從這裏打開 Latte Dock：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/02_latte_in_drawer.webp?resize=800%2C450&amp;ssl=1" alt="應用抽屜裏高亮顯示的 Latte dock"></p><p>酷！現在你的桌面上已經打開了 Latte Dock。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/03_latte_dock_launched.webp?resize=800%2C450&amp;ssl=1" alt="桌面上的 Latte Dock 屏幕截圖"></p><h4 id="啓用-latte-dock-的自動啓動功能" tabindex="-1">啓用 Latte Dock 的自動啓動功能 <a class="header-anchor" href="#啓用-latte-dock-的自動啓動功能" aria-label="Permalink to “啓用 Latte Dock 的自動啓動功能”">​</a></h4><p>隨着 Latte Dock 的打開，以及 Ubuntu 自帶停靠區的禁用，如果你現在重啓，那麼下次你的電腦開機時就不會有任何停靠區了。</p><p>讓我們現在就來解決這個問題。</p><p>在停靠區上點擊右鍵。點擊“<ruby>佈局<rt>Layouts</rt></ruby>”子菜單下的“<ruby>配置<rt>Configure</rt></ruby>”選項。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/configure-latte-dock.png?resize=800%2C392&amp;ssl=1" alt="通過進入“佈局” -&gt; “配置” 啓動設置面板窗口"></p><p>現在，在“<ruby>偏好<rt>Preferences</rt></ruby>”選項卡下，確保“<ruby>在啓動時啓用自動啓動<rt>Enable autostart during startup</rt></ruby>”複選框被選中。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/enable_autostart_latte_dock.webp?resize=800%2C433&amp;ssl=1" alt="啓用啓動時自動啓動複選框"></p><h3 id="定製你的停靠區" tabindex="-1">定製你的停靠區 <a class="header-anchor" href="#定製你的停靠區" aria-label="Permalink to “定製你的停靠區”">​</a></h3><p>如果你安裝了任何 KDE 的產品，定製應該是永無止境的。如果 Latte Dock 不允許定製，那就奇怪了。幸運的是，情況並非如此。</p><p>你可以做各種各樣的事情來定製 Latte Dock。增加它的大小，使它更透明或半透明，為它設計主題等等。</p><h4 id="將應用程序固定在停靠區上" tabindex="-1">將應用程序固定在停靠區上 <a class="header-anchor" href="#將應用程序固定在停靠區上" aria-label="Permalink to “將應用程序固定在停靠區上”">​</a></h4><p>要把你的應用程序固定在 Latte Dock 上，打開該應用程序，右鍵點擊在你停靠區中的應用程序圖標。現在點擊“<ruby>固定啓動器<rt></rt>Pin Launcher</ruby>”。完成了！你的應用程序現在已經被固定到了停靠區上。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/pin-app-latte-dock.webp?resize=800%2C334&amp;ssl=1" alt="右擊正在運行的應用程序並選擇釘住啓動器選項"></p><p>你可以通過點擊和拖動移動它到左邊或右邊來改變它在停靠區中的位置。</p><h4 id="搜索和安裝-latte-dock-主題" tabindex="-1">搜索和安裝 Latte Dock 主題 <a class="header-anchor" href="#搜索和安裝-latte-dock-主題" aria-label="Permalink to “搜索和安裝 Latte Dock 主題”">​</a></h4><p>通過右擊停靠區打開 Latte Dock 的“<ruby>設置<rt>Settings</rt></ruby>”窗口，點擊“<ruby>佈局<rt>Layout</rt></ruby>”子菜單下的“<ruby>配置<rt>Configure</rt></ruby>”選項。</p><p>你可能已經安裝了一些主題（呃...佈局）。從已安裝的選項列表中選擇它，然後點擊右側的切換按鈕。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/change-themes-latte-dock.webp?resize=800%2C393&amp;ssl=1" alt="改變 Latte Dock 的主題"></p><p>你也可以通過點擊“<ruby>下載<rt>Download</rt></ruby>”按鈕來下載更多的主題。它應該向你顯示一個可用的主題列表，以供安裝。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/11/08_download_layouts.webp?resize=800%2C450&amp;ssl=1" alt="Latte Dock 插件安裝窗口"></p><h4 id="改變停靠區的外觀和行為" tabindex="-1">改變停靠區的外觀和行為 <a class="header-anchor" href="#改變停靠區的外觀和行為" aria-label="Permalink to “改變停靠區的外觀和行為”">​</a></h4><p>正如我前面提到的，在 KDE 產品中有大量的定製選項。</p><p>讓我們來試試。</p><p>右鍵點擊停靠區，點擊 “<ruby>停靠區設置<rt>Dock Settings</rt></ruby>”。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/latte_dock_settings.webp?resize=799%2C246&amp;ssl=1" alt="通過右鍵點擊停靠區進入 Latte Dock 設置"></p><p>在這裏，你會得到各種類型的可以切換的選項。想把停靠區移到顯示器的左側嗎？你可以通過“<ruby>位置<rt> Location</rt></ruby>”子菜單下提供的選項來實現。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/11_customization_options.webp?resize=800%2C450&amp;ssl=1" alt="Dock 設置和定製窗口"></p><p>如果你覺得可用的選項有任何限制，請撥動右上角的“<ruby>高級<rt>Advanced</rt></ruby>”開關。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/12_customization_options_advanced.webp?resize=800%2C450&amp;ssl=1" alt="現在可以看到帶有高級選項的停靠區設置和定製窗口"></p><p>現在看起來真是太棒了！</p><p>試着切換每個可用的開關。你可以延遲隱藏停靠區。你可以把它放在顯示器的一個邊緣，把它放在該邊緣的中心、左邊或右邊。你可以做到這一切。</p><p>想修飾啓動、懸停等效果？在“<ruby>效果<rt>Effects</rt></ruby>”選項卡下有更多的調整選項等待着你。</p><h3 id="從你的系統中刪除-latte-dock" tabindex="-1">從你的系統中刪除 Latte Dock <a class="header-anchor" href="#從你的系統中刪除-latte-dock" aria-label="Permalink to “從你的系統中刪除 Latte Dock”">​</a></h3><p>你安裝了 Latte Dock，並對其進行了定製，但覺得它不是你想要的東西。而你現在正在尋找刪除 Latte Dock 的方法。很好，我幫你。</p><p>你可以使用 <code>apt</code> 軟件包管理器刪除 Latte Dock。用下面的命令來做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt autoremove --purge latte-dock</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/15_apt_get_remove.webp?resize=800%2C450&amp;ssl=1" alt=""></p><p><code>--purge</code> 標誌將刪除 Latte Dock 在系統目錄中的任何配置文件，除了 <code>~/.config</code>。</p><h4 id="僅供高級用户使用-刪除用户特定的遺留文件" tabindex="-1">僅供高級用户使用：刪除用户特定的遺留文件 <a class="header-anchor" href="#僅供高級用户使用-刪除用户特定的遺留文件" aria-label="Permalink to “僅供高級用户使用：刪除用户特定的遺留文件”">​</a></h4>',51)),i("p",null,[t[6]||(t[6]=a("這不是強制性的，但如果你想刪除通常放在 ",-1)),t[7]||(t[7]=i("code",null,"$HOME/.config",-1)),t[8]||(t[8]=a("（即 ",-1)),t[9]||(t[9]=i("code",null,"~/.config",-1)),t[10]||(t[10]=a("）目錄中的用户配置文件。",-1)),s(e,{href:"https://linuxhandbook.com/find-command-examples/"},{default:o(()=>[...t[5]||(t[5]=[a("使用 find 命令",-1)])]),_:1}),t[11]||(t[11]=a(" 來定位 Latte Dock 的配置文件：",-1))]),t[30]||(t[30]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~/.config -iname &quot;latte*&quot;</span></span></code></pre></div><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/13_find_configs.webp?resize=800%2C450&amp;ssl=1" alt=""></p><p>你可以安全地從你的 <code>~/.config</code> 目錄中刪除這些目錄和配置文件。</p><h4 id="對於-ubuntu-用户-重新啓用-ubuntu-停靠區" tabindex="-1">對於 Ubuntu 用户：重新啓用 Ubuntu 停靠區 <a class="header-anchor" href="#對於-ubuntu-用户-重新啓用-ubuntu-停靠區" aria-label="Permalink to “對於 Ubuntu 用户：重新啓用 Ubuntu 停靠區”">​</a></h4><p>不要忘了啓用 Ubuntu 的停靠區。如果你不記得了，再次啓用停靠區的命令在下面：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gnome-extensions enable ubuntu-dock@ubuntu.com</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Latte Dock 是一個來自 KDE 社區的令人驚豔的停靠區 ( ͡° ͜ʖ ͡°)</p><p>它提供了大量的主題（佈局）、外觀和自定義選項，以及一些漂亮的效果。如果你正在考慮定製你的桌面外觀和感覺，它肯定是你應該尋找的東西。</p><p>如果你最終喜歡上了 Latte Dock 並開始每天使用它，請在評論中告訴我。如果你不喜歡 Latte Dock，也請發表評論讓我知道原因。</p><hr>',11)),i("p",null,[t[13]||(t[13]=a("via: ",-1)),s(e,{href:"https://itsfoss.com/install-use-latte-dock-ubuntu/"},{default:o(()=>[...t[12]||(t[12]=[a("https://itsfoss.com/install-use-latte-dock-ubuntu/",-1)])]),_:1})]),i("p",null,[t[18]||(t[18]=a("作者：",-1)),s(e,{href:"https://itsfoss.com/author/pratham/"},{default:o(()=>[...t[14]||(t[14]=[a("Pratham Patel",-1)])]),_:1}),t[19]||(t[19]=a(" 選題：",-1)),s(e,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[15]||(t[15]=[a("lujun9972",-1)])]),_:1}),t[20]||(t[20]=a(" 譯者：",-1)),s(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[16]||(t[16]=[a("wxy",-1)])]),_:1}),t[21]||(t[21]=a(" 校對：",-1)),s(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[17]||(t[17]=[a("wxy",-1)])]),_:1})]),i("p",null,[t[24]||(t[24]=a("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[22]||(t[22]=[a("LCTT",-1)])]),_:1}),t[25]||(t[25]=a(" 原創編譯，",-1)),s(e,{href:"https://linux.cn/"},{default:o(()=>[...t[23]||(t[23]=[a("Linux中國",-1)])]),_:1}),t[26]||(t[26]=a(" 榮譽推出",-1))])])}const y=p(d,[["render",b]]);export{D as __pageData,y as default};
